// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define TLV_RC_NO_ERROR 0
#define TLV_RC_NO_MORE_TLVS 1
#define TLV_RC_SIZE_ERROR 2

typedef struct tlv_raw {
  uint8_t raw_type[2];
  uint8_t raw_length[4];
} TLV_RAW;

typedef struct tlv {
  uint16_t type;
  uint32_t length;
  const uint8_t *value;
} TLV;

typedef struct fuzz_parse_state {
  const uint8_t *data;
  size_t data_len;
  size_t data_pos;
} FUZZ_PARSE_STATE;

typedef struct fuzz_data {
  FUZZ_PARSE_STATE state;
} FUZZ_DATA;

static uint32_t to_u32(const uint8_t b[4]) {
  return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16) |
         ((uint32_t)b[2] << 8) | (uint32_t)b[3];
}

static uint16_t to_u16(const uint8_t b[2]) {
  return (uint16_t)((uint16_t)b[0] << 8) | (uint16_t)b[1];
}

int fuzz_get_first_tlv(FUZZ_DATA *fuzz, TLV *tlv) {
  // Intentionally flawed header-size-only bounds check (does not account for value length)
  if(!fuzz || !tlv || !fuzz->state.data) return TLV_RC_SIZE_ERROR;
  if(fuzz->state.data_len - fuzz->state.data_pos < sizeof(TLV_RAW))
    return TLV_RC_NO_MORE_TLVS;

  const uint8_t *p = fuzz->state.data + fuzz->state.data_pos;
  const TLV_RAW *raw = (const TLV_RAW *)p;
  tlv->type = to_u16(raw->raw_type);
  tlv->length = to_u32(raw->raw_length);
  tlv->value = p + sizeof(TLV_RAW);

  // BUG: does not verify that tlv->length bytes are actually available before touching the last byte
  if(tlv->length > 0) {
    volatile uint8_t sink = tlv->value[tlv->length - 1];
    (void)sink;
  }

  // Advance cursor regardless of whether enough data remained for value
  fuzz->state.data_pos += sizeof(TLV_RAW) + tlv->length;
  if(fuzz->state.data_pos > fuzz->state.data_len)
    return TLV_RC_SIZE_ERROR;
  return TLV_RC_NO_ERROR;
}

driver_c:
// driver.c
#include <klee/klee.h>
#include "harness.c"

int main() {
  FUZZ_DATA fuzz;
  memset(&fuzz, 0, sizeof(fuzz));

  uint8_t buf[16];
  size_t len;
  klee_make_symbolic(&len, sizeof(len), "len");
  if(len > sizeof(buf)) len = sizeof(buf);
  klee_make_symbolic(buf, sizeof(buf), "buf");

  fuzz.state.data = buf;
  fuzz.state.data_len = len;
  fuzz.state.data_pos = 0;

  TLV tlv;
  fuzz_get_first_tlv(&fuzz, &tlv);
  return 0;
}

