  if(tlv->length) {
    volatile uint8_t b = tlv->value[tlv->length - 1];
    (void)b;
  }

  fuzz->state.data_pos += sizeof(TLV_RAW) + tlv->length;
  return TLV_RC_NO_ERROR;
}

