// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define TLV_TYPE_HTTPPOSTBODY 52

typedef struct tlv {
  uint16_t type;
  uint32_t length;
  const uint8_t *value;
} TLV;

typedef struct fuzz_data {
  char *post_body;
} FUZZ_DATA;

// Intentionally vulnerable: integer overflow + memcpy overflow
void fuzz_setup_http_post(FUZZ_DATA *fuzz, TLV *tlv) {
  if(!fuzz || !tlv) return;
  if(tlv->type != TLV_TYPE_HTTPPOSTBODY) return;
  // BUG: uses signed int for size computation, allowing overflow and undersized allocation
  int sz = (int)tlv->length + 1; // if length is large, sz may wrap
  if(sz <= 0) sz = 1;
  fuzz->post_body = (char *)malloc((size_t)sz);
  if(!fuzz->post_body) return;
  // BUG: copies full tlv->length bytes regardless of allocated size
  memcpy(fuzz->post_body, tlv->value, tlv->length);
  // not null-terminating safely either
}

