  klee_make_symbolic(&tlv.length, sizeof(tlv.length), "len");
  // keep length large enough to trigger overflow/copy issues
  if(tlv.length < 32) tlv.length = 32;

  uint8_t smallbuf[8];
  klee_make_symbolic(smallbuf, sizeof(smallbuf), "smallbuf");
  tlv.value = smallbuf; // too small for tlv.length

  fuzz_setup_http_post(&fuzz, &tlv);
  return 0;
}

