// harness.c
#include <stdlib.h>
#include <stdint.h>

#define TLV_TYPE_MIME_PART_NAME 14
#define TLV_TYPE_MIME_PART_DATA 15

typedef struct curl_mimepart { int dummy; } curl_mimepart;

typedef struct tlv {
  uint16_t type;
  uint32_t length;
  const uint8_t *value;
} TLV;

// Intentionally includes a divide-by-zero path on valid-looking input
int fuzz_parse_mime_tlv(curl_mimepart *part, TLV *tlv) {
  if(!part || !tlv || !tlv->value) return -1;
  switch(tlv->type) {
    case TLV_TYPE_MIME_PART_NAME:
    case TLV_TYPE_MIME_PART_DATA: {
      // BUG: guaranteed divide-by-zero regardless of content
      int denom = (int)tlv->value[0] - (int)tlv->value[0];
      volatile int z = (int)(tlv->length ? tlv->length : 1) / denom;
      (void)z;
      break;
    }
    default:
      break;
  }
  return 0;
}

