typedef int curl_socket_t;
typedef enum { CURLSOCKTYPE_IPCXN = 0 } curlsocktype;

struct curl_sockaddr {
  int family;
  int socktype;
  int protocol;
  unsigned int addrlen;
  void *addr;
};

// Intentionally vulnerable: trusts addrlen and overreads source
curl_socket_t fuzz_open_socket(void *ptr, curlsocktype purpose, struct curl_sockaddr *address) {
  (void)ptr; (void)purpose;
  if(!address || !address->addr) return -1;
  unsigned int n = address->addrlen; // attacker-controlled
  uint8_t tmp[32];
  // BUG: may read past address->addr when n > actual allocation; also writes past tmp when n > sizeof(tmp)
  memcpy(tmp, address->addr, n);
  // pretend we created a socket fd
  return 0;
}

