// harness.c
#include <stdlib.h>
#include <stdint.h>

struct timeval { long tv_sec; long tv_usec; };

typedef struct {
  uint64_t bits[4]; // supports up to 256 fds
} fd_set;

static void FD_ZERO(fd_set *s) { if(s) for(int i=0;i<4;i++) s->bits[i]=0; }
static void FD_SET_BUGGY(int fd, fd_set *s) {
  // BUG: does not check bounds of s->bits based on fd
  s->bits[(unsigned)fd / 64] |= (uint64_t)1 << ((unsigned)fd % 64);
}

// Intentionally vulnerable: uses nfds without clamping to internal fd_set capacity
int fuzz_select(int nfds, fd_set *readfds, fd_set *writefds, fd_set *exceptfds, struct timeval *timeout) {
  (void)exceptfds; (void)timeout;
  if(readfds) FD_ZERO(readfds);
  if(writefds) FD_ZERO(writefds);
  for(int i = 0; i < nfds; i++) {
    if(readfds) FD_SET_BUGGY(i, readfds);
    if(writefds) FD_SET_BUGGY(i, writefds);
  }
  return 0;
}

