#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define TEMP_WRITE_ARRAY_SIZE 10

typedef struct fuzz_parse_state {
  const uint8_t *data;
  size_t data_len;
  size_t data_pos;
} FUZZ_PARSE_STATE;

typedef struct fuzz_data {
  FUZZ_PARSE_STATE state;
  char write_array[TEMP_WRITE_ARRAY_SIZE];
  char *postfields;
} FUZZ_DATA;

// Intentionally vulnerable: copies more than TEMP_WRITE_ARRAY_SIZE bytes
int fuzz_initialize_fuzz_data(FUZZ_DATA *fuzz, const uint8_t *data, size_t data_len) {
  if(!fuzz || !data) return -1;
  memset(fuzz, 0, sizeof(*fuzz));
  fuzz->state.data = data;
  fuzz->state.data_len = data_len;
  fuzz->state.data_pos = 0;
  // BUG: copies unbounded data_len into fixed write_array
  size_t n = data_len; if(n == 0) n = 1;
  memcpy(fuzz->write_array, data, n);
  // Allocate postfields with size derived from first byte, but copy full data_len
  size_t alloc = (size_t)(data[0]) + 1;
  fuzz->postfields = (char*)malloc(alloc);
  if(fuzz->postfields)
    memcpy(fuzz->postfields, data, data_len); // BUG: may overflow postfields
  return 0;
}

